@pytest.mark.parametrize("name", panels.PANEL_NAMES)
def test_stationery_defaults_serialize_to_their_record_size(name):
    record = panels.defaults()[name].to_bytes()
    assert len(record) == len(CASES[0][1][name])
    assert record[:2] == CASES[0][1][name][:2], "record version"


def test_optimizer_bytes():
    # MSL C.PPC.MTrgt.mcp 'MSL C PPC Release' record: level 4, optimize for speed
    assert panels.PPCGlobalOptimizerPanel(
        level=4, optfor=0
    ).to_bytes() == bytes.fromhex("00010400" + "00" * 8)
    assert panels.PPCGlobalOptimizerPanel(
        level=4, optfor=1
    ).to_bytes() == bytes.fromhex("00010401" + "00" * 8)
